writeFileSync(join(root,'sections.html'),`<!-- @overview:vision --><p class="deck">Инсайт: {{INSIGHT}}</p><div class="utp-box">{{TAGLINE}}</div><p>Если убрать offline-пакет, путевые точки, фоновый трек и сборку отчёта, продукт рассыпается. Лента, лайки, подписчики и публичные профили отсутствуют не визуально, а в модели мира.</p>{{FEAT_GRID}}<!-- @end --><!-- @overview:arch --><p class="deck">Каждый доступ вызывается видимым жестом внутри полезной функции; на старте журнал не показывает системных запросов.</p><div class="flow"><span class="chip">Маршрут</span><span class="arr">→</span><span class="chip">Карта</span><span class="arr">→</span><span class="chip">Location</span><span class="arr">→</span><span class="chip">точка пути</span></div><div class="flow"><span class="chip">Новая точка</span><span class="arr">→</span><span class="chip">камера / Фото / голос</span><span class="arr">→</span><span class="chip">наблюдение в журнале</span></div><div class="flow"><span class="chip">Ещё</span><span class="arr">→</span><span class="chip">Отчёт</span><span class="arr">→</span><span class="chip">BG Processing</span><span class="arr">→</span><span class="chip">PDF</span></div><div class="arch"><div class="arch-layer"><h3>UI</h3><p>24 экрана, четыре корневых инструмента: маршрут, журнал, снаряжение, ещё.</p></div><div class="arch-layer"><h3>Domain</h3><p>Выход содержит точки, наблюдения, оборудование и производный отчёт.</p></div><div class="arch-layer"><h3>Data</h3><p>CoreData, файлы пользователя, Keychain. Полевой сценарий полностью локален.</p></div><div class="arch-layer"><h3>External</h3><p>MapKit, SDK опционального входа, APNs и партнёрский SDK. Приложение не является спасательной службой.</p></div></div><!-- @end --><section class="section" id="perm-matrix"><h2>Матрица доступов</h2><p class="deck">Все 20 доступов ОК: функция, жест, состояние и рабочий отказ.</p>{{PERM_MATRIX}}</section><section class="section" id="no-backend"><h2>Автономная архитектура</h2>{{BACKENDLESS}}</section><section class="section" id="screen-table"><h2>Экраны и доступы</h2>{{SCREEN_TABLE}}</section><section class="section"><h2>Визуальная система</h2><div class="feat-grid"><div class="feat"><h3>Полевой шифр</h3><p>Координаты, время и статусы набраны моноширинно.</p></div><div class="feat"><h3>Бумага и уголь</h3><p>Тёплая бумага для планирования, тёмный уголь для поля.</p></div><div class="feat"><h3>Сигнальный оранжевый</h3><p>Только маршрут, активное действие и важный статус.</p></div><div class="feat"><h3>Без карточного шума</h3><p>Данные держатся на линиях, шкалах и хронологии.</p></div></div></section>\n`);

const docs = {
'01-product-vision.md':'# Экспедиция — product vision\n\nПолевой журнал группового маршрута для учебных, научных и краеведческих выходов 13+. Единица продукта — выход, не человек и не публикация. Аккаунт опционален; локальный режим полноценен. Приложение не является спасательной службой.\n',
'02-architecture.md':'# Архитектура\n\nЛокальные сущности: выход, точка, наблюдение, предмет снаряжения и отчёт. PermissionService — единственная точка системных запросов. CoreData хранит метаданные, FileManager — медиа, Keychain — сессию и ключ пакета.\n\n<!-- @generated:ia-tree:start -->\n<!-- @generated:ia-tree:end -->\n\n<!-- @generated:transitions:start -->\n<!-- @generated:transitions:end -->\n',
'03-design-system.md':'# Дизайн-система\n\nТёплая полевая бумага `#F3F0E7`, уголь `#101713`, сигнальный оранжевый `#E4572E`, мох `#315B47`. Manrope для интерфейса, IBM Plex Mono для координат, времени и статусов. Радиусы сдержанные: 4 для карты и отчёта, 10 для контролов.\n',
'04-references.md':'# Референсы и отстройка\n\nЗнакомые паттерны: offline-карта, хронологический журнал, чек-лист. От Одноклассников сохранена только понятность массового мобильного интерфейса; лента, профили, подписчики, классы и публичная коммуникация отсутствуют.\n',
'05-visual-audit.md':'# Визуальный аудит\n\nПроход 1: карта стала доминантой первого экрана, убрана сетка одинаковых карточек. Проход 2: добавлены видимые offline, denied, loading, empty и error-состояния; главные действия имеют hit-target не меньше 44 pt.\n',
'06-app-store.md':'# App Store\n\nPrimary category: Navigation. Secondary: Education. Возраст 13+. Вход не обязателен. Удаление аккаунта доступно в «Ещё». Support, Terms и Privacy доступны до входа и внутри приложения.\n',
'07-quality-evidence.md':'# Quality evidence\n\nПроверяются гостевой старт без промптов, три полевых способа наблюдения, отказ каждого доступа, offline-пакет, фоновый трек с явной остановкой, полевая связь не как 112, сборка и экспорт отчёта.\n'};
for (const [name,body] of Object.entries(docs)) writeFileSync(join(root,'docs',name),body);
console.log('Экспедиция: concept, screens, styles and docs generated');
